import { tv } from "tailwind-variants";

/*
Slots and their data-attributes and css variables:

root: data-open/data-closed/data-starting-style/data-ending-style
trigger: data-panel-open
panel: data-open/data-closed/data-starting-style/data-ending-style; --collapsible-panel-height/--collapsible-panel-width
*/

const collapsible = tv({
  slots: {
    root: "",
    trigger: "group",
    panel: [
      "h-(--collapsible-panel-height) overflow-hidden transition-[height] duration-300 ease-default",
      "data-disabled:opacity-50",
      "data-ending-style:h-0",
      "data-starting-style:h-0",
    ],
  },
});

export { collapsible };

"use client";

import { useDirection } from "@base-ui/react";
import { Collapsible as BaseCollapsible } from "@base-ui/react/collapsible";

import { mergeSlotClassName } from "@/registry/sector23/lib/merge-base-ui";

import { collapsible } from "./collapsible.style";

function Collapsible({ className, ...props }: BaseCollapsible.Root.Props) {
  const direction = useDirection();

  return (
    <BaseCollapsible.Root
      data-slot="collapsible"
      className={mergeSlotClassName(collapsible().root, className)}
      {...props}
      dir={direction}
    />
  );
}

function CollapsibleTrigger({
  className,
  ...props
}: BaseCollapsible.Trigger.Props) {
  return (
    <BaseCollapsible.Trigger
      data-slot="collapsible-trigger"
      className={mergeSlotClassName(collapsible().trigger, className)}
      {...props}
    />
  );
}

function CollapsiblePanel({
  className,
  ...props
}: BaseCollapsible.Panel.Props) {
  return (
    <BaseCollapsible.Panel
      data-slot="collapsible-panel"
      className={mergeSlotClassName(collapsible().panel, className)}
      {...props}
    />
  );
}

export { Collapsible, CollapsibleTrigger, CollapsiblePanel };
